SELECT *
FROM (
SELECT ROW_NUMBER() OVER(ORDER BY PRODUCT_ID DESC) RN,
P.*
FROM PRODUCT P
)
WHERE RN BETWEEN #{startRow}
AND #{endRow}

SELECT *
FROM (
SELECT ROW_NUMBER() OVER(ORDER BY PRODUCT_ID DESC) RN,
P.*
FROM PRODUCT P
WHERE CATEGORY_ID = #{categoryId}
)
WHERE RN BETWEEN #{startRow}
AND #{endRow}

SELECT COUNT(*)
FROM PRODUCT
WHERE CATEGORY_ID = #{categoryId}
